<?php
declare(strict_types=1);
final class PluginRunner { public function __construct(private readonly array $config){} public function test(array $m):array{$name=(string)($m['name']??'');$tools=(array)($m['tools']??[]);if(!preg_match('/^[a-zA-Z0-9._-]{2,80}$/',$name))throw new InvalidArgumentException('Nome inválido.');$valid=[];foreach($tools as $t){if(!is_array($t)||!preg_match('/^[a-zA-Z0-9._-]{2,80}$/',(string)($t['name']??'')))return ['ok'=>false,'error'=>'Ferramenta inválida.'];$valid[]=['name'=>$t['name'],'description'=>(string)($t['description']??''),'mode'=>'declarative'];}return ['ok'=>true,'plugin'=>$name,'tools'=>$valid,'executed_code'=>false,'message'=>'Manifesto validado em modo seguro; nenhum código do sistema foi executado.'];} public function execute(array $m,string $tool,array $args):array{$r=$this->test($m);foreach($r['tools'] as $t)if($t['name']===$tool)return ['ok'=>true,'plugin'=>$m['name'],'tool'=>$tool,'arguments'=>$args,'mode'=>'dry-run','message'=>'Execução de teste concluída; plugins só podem usar ferramentas explicitamente permitidas.'];throw new InvalidArgumentException('Ferramenta não declarada pelo plugin.');}}
?>
